candidates.raw:
    size_t i;
    double req[3];
    double raw[3];

    if ((requested == NULL) || (area_turns == NULL) || (resistance == NULL) ||
        (voltage_limit == NULL) || (voltage == NULL) || (realized == NULL) || (mask == NULL)) {
        return ADCS_E_NULL;
    }

    voltage->x = 0.0;
    voltage->y = 0.0;
    voltage->z = 0.0;
    realized->x = 0.0;
    realized->y = 0.0;
    realized->z = 0.0;
    *mask = 0U;

    if ((!isfinite(requested->x)) || (!isfinite(requested->y)) || (!isfinite(requested->z))) {
        return ADCS_E_RANGE;
    }
    for (i = 0; i < 3U; i++) {
        if ((!isfinite(area_turns[i])) || (area_turns[i] <= 0.0)) {
            return ADCS_E_RANGE;
        }
        if ((!isfinite(resistance[i])) || (resistance[i] <= 0.0)) {
            return ADCS_E_RANGE;
        }
        if ((!isfinite(voltage_limit[i])) || (voltage_limit[i] < 0.0)) {
            return ADCS_E_RANGE;
        }
    }

    req[0] = requested->x;
    req[1] = requested->y;
    req[2] = requested->z;

    for (i = 0; i < 3U; i++) {
        raw[i] = resistance[i] * req[i] / area_turns[i];
    }

    for (i = 0; i < 3U; i++) {
        if (raw[i] > voltage_limit[i]) {
            raw[i] = voltage_limit[i];
            *mask |= (unint32)(1U << i);
        } else if (raw[i] < -voltage_limit[i]) {
            raw[i] = -voltage_limit[i];
            *mask |= (unint32)(1U << i);
        }
    }

    voltage->x = raw[0];
    voltage->y = raw[1];
    voltage->z = raw[2];

    realized->x = voltage->x * area_turns[0] / resistance[0];
    realized->y = voltage->y * area_turns[1] / resistance[1];
    realized->z = voltage->z * area_turns[2] / resistance[2];

    return ADCS_OK;
}

